import json
import itertools

def solve_puzzle():
    # Houses numbered left (1) to right (2)
    houses = [1, 2]

    # Attributes and their possible values
    attributes = {
        "name": ["Arnold", "Eric"],
        "favorite sports": ["basketball", "soccer"],
        "hair colors": ["brown", "black"],
        "heights": ["very short", "short"],
        "favorite smoothie": ["desert", "cherry"],
        "favorite flower": ["daffodils", "carnations"],
    }

    # Helper to get index of a value in a permutation assignment
    def index_of(perm, value):
        return perm.index(value)

    solutions = []

    # Iterate over all permutations for each category
    for names in itertools.permutations(attributes["name"]):
        for sports in itertools.permutations(attributes["favorite sports"]):
            # Clue 1: The person who loves soccer is not in the second house.
            if sports[1] == "soccer":
                continue

            for hair in itertools.permutations(attributes["hair colors"]):
                for heights in itertools.permutations(attributes["heights"]):
                    # Clue 3: The person who is very short is the person who has brown hair.
                    pos_vs = index_of(heights, "very short")
                    if hair[pos_vs] != "brown":
                        continue

                    for smoothies in itertools.permutations(attributes["favorite smoothie"]):
                        # Clue 2: The Desert smoothie lover is directly left of the person who is very short.
                        if "desert" not in smoothies:
                            continue
                        pos_desert = index_of(smoothies, "desert")
                        if not (pos_desert + 1 == pos_vs):
                            continue

                        for flowers in itertools.permutations(attributes["favorite flower"]):
                            # Clue 4: The person who loves a carnations arrangement is the Desert smoothie lover.
                            if flowers[pos_desert] != "carnations":
                                continue

                            # Clue 5: Eric and the person who has brown hair are next to each other.
                            pos_eric = index_of(names, "Eric")
                            pos_brown = index_of(hair, "brown")
                            if abs(pos_eric - pos_brown) != 1:
                                continue

                            # If all constraints satisfied, record solution
                            solution = {
                                "House": [str(h) for h in houses],
                                "name": list(names),
                                "favorite sports": list(sports),
                                "hair colors": list(hair),
                                "heights": list(heights),
                                "favorite smoothie": list(smoothies),
                                "favorite flower": list(flowers),
                            }
                            solutions.append(solution)

    # Expect exactly one solution
    if not solutions:
        raise RuntimeError("No solution found.")
    # If multiple solutions, choose the first (shouldn't happen for well-posed puzzle)
    sol = solutions[0]

    header = ["House", "name", "favorite sports", "hair colors", "heights", "favorite smoothie", "favorite flower"]
    rows = []
    for i in range(len(houses)):
        row = [
            sol["House"][i],
            sol["name"][i],
            sol["favorite sports"][i],
            sol["hair colors"][i],
            sol["heights"][i],
            sol["favorite smoothie"][i],
            sol["favorite flower"][i],
        ]
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
